            {
                FirstMidName = "Kim",
                LastName = "Abercrombie",
                HireDate = DateTime.Parse("1995-03-11"),
                CourseAssignments = new List<CourseAssignment>()
            };
            context.Instructors.Add(instructor);
            context.SaveChanges();

            // Update dept with instructor
            dept.InstructorID = instructor.ID;
            context.SaveChanges();

            var course = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = dept.DepartmentID,
                CourseAssignments = new List<CourseAssignment>()
            };
            context.Courses.Add(course);
            context.SaveChanges();

            var enrollment = new Enrollment
            {
                StudentID = students[0].ID,
                CourseID = course.CourseID,
                Grade = Grade.A
            };
            context.Enrollments.Add(enrollment);
            context.SaveChanges();
        }

        /// <summary>
        /// Drain the static NotificationService queue to prevent cross-test interference
        /// </summary>
        public static void DrainNotificationQueue()
        {
