using System;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _service;

        public NotificationServiceTests()
        {
            _service = new NotificationService();
            // Drain queue to isolate tests from each other
            TestDbContextHelper.DrainNotificationQueue();
        }

        public void Dispose()
        {
            _service.Dispose();
            TestDbContextHelper.DrainNotificationQueue();
        }

        [Fact]
        public void SendNotification_WithDisplayName_EnqueuesNotification()
        {
            _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "admin");

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Contains("John Doe", notification.Message);
            Assert.Contains("created", notification.Message);
            Assert.Equal("admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesEntityId()
        {
            _service.SendNotification("Course", "42", null, EntityOperation.UPDATE, "admin");

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Contains("ID: 42", notification.Message);
            Assert.Contains("updated", notification.Message);
        }

        [Fact]
        public void SendNotification_WithoutUserName_DefaultsToSystem()
        {
            _service.SendNotification("Student", "1", EntityOperation.CREATE);

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Theory]
        [InlineData(EntityOperation.CREATE, "created")]
        [InlineData(EntityOperation.UPDATE, "updated")]
        [InlineData(EntityOperation.DELETE, "deleted")]
        public void GenerateMessage_DifferentOperations_ProducesCorrectVerb(EntityOperation operation, string expectedVerb)
        {
            _service.SendNotification("Student", "1", "Test Student", operation, "user");

            var notification = _service.ReceiveNotification();

            Assert.Contains(expectedVerb, notification.Message);
        }

        [Fact]
        public void SendNotification_WithDisplayName_IncludesNameInQuotes()
        {
            _service.SendNotification("Department", "5", "Engineering", EntityOperation.CREATE, "user");

            var notification = _service.ReceiveNotification();

            Assert.Equal("New Department 'Engineering' has been created", notification.Message);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_IncludesIdFormat()
        {
            _service.SendNotification("Department", "5", null, EntityOperation.DELETE, "user");

            var notification = _service.ReceiveNotification();

            Assert.Equal("Department (ID: 5) has been deleted", notification.Message);
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            var result = _service.ReceiveNotification();

            Assert.Null(result);
        }

        [Fact]
        public void ReceiveNotification_MultipleMessages_DequeuedInOrder()
        {
            _service.SendNotification("A", "1", EntityOperation.CREATE, "user");
            _service.SendNotification("B", "2", EntityOperation.UPDATE, "user");
            _service.SendNotification("C", "3", EntityOperation.DELETE, "user");

            var first = _service.ReceiveNotification();
            var second = _service.ReceiveNotification();
            var third = _service.ReceiveNotification();
            var fourth = _service.ReceiveNotification();

            Assert.Equal("A", first.EntityType);
            Assert.Equal("B", second.EntityType);
            Assert.Equal("C", third.EntityType);
            Assert.Null(fourth);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // MarkAsRead is a no-op but should not throw
            var exception = Record.Exception(() => _service.MarkAsRead(42));

            Assert.Null(exception);
        }

        [Fact]
        public void SendNotification_OverloadWithoutDisplayName_Works()
        {
            _service.SendNotification("Instructor", "10", EntityOperation.UPDATE, "admin");

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Instructor", notification.EntityType);
            Assert.Equal("10", notification.EntityId);
            Assert.Equal("UPDATE", notification.Operation);
            Assert.Contains("Instructor (ID: 10)", notification.Message);
        }

        [Fact]
        public void SendNotification_SetsCreatedAtToNow()
        {
            var before = DateTime.Now.AddSeconds(-1);

            _service.SendNotification("Test", "1", EntityOperation.CREATE);

            var notification = _service.ReceiveNotification();
            var after = DateTime.Now.AddSeconds(1);

            Assert.InRange(notification.CreatedAt, before, after);
        }

        [Fact]
        public void Dispose_CalledMultipleTimes_DoesNotThrow()
        {
            var service = new NotificationService();

            var exception = Record.Exception(() =>
            {
                service.Dispose();
                service.Dispose();
            });

            Assert.Null(exception);
        }

        [Fact]
        public void SendNotification_WhitespaceDisplayName_UsesIdFormat()
        {
            _service.SendNotification("Course", "7", "   ", EntityOperation.UPDATE, "user");

            var notification = _service.ReceiveNotification();

            Assert.Contains("ID: 7", notification.Message);
        }

        [Fact]
        public void SendNotification_EmptyDisplayName_UsesIdFormat()
        {
            _service.SendNotification("Course", "7", "", EntityOperation.UPDATE, "user");

            var notification = _service.ReceiveNotification();

            Assert.Contains("ID: 7", notification.Message);
        }
    }
}

