+        private class TestPerson : Person { }
+
+        [Theory]
+        [InlineData("Doe", "John", "Doe, John")]
+        [InlineData("Smith", "Jane", "Smith, Jane")]
+        [InlineData("O'Brien", "Mary", "O'Brien, Mary")]
+        public void FullName_ReturnsLastNameCommaFirstName(string lastName, string firstName, string expected)
+        {
+            var person = new TestPerson { LastName = lastName, FirstMidName = firstName };
+
+            Assert.Equal(expected, person.FullName);
+        }
+
+        [Fact]
+        public void FullName_WithNullParts_StillConcatenates()
+        {
+            var person = new TestPerson { LastName = null, FirstMidName = null };
+
+            Assert.Equal(", ", person.FullName);
+        }
+
+        [Fact]
+        public void ID_DefaultsToZero()
+        {
+            var person = new TestPerson();
+
+            Assert.Equal(0, person.ID);
+        }
+
+        [Fact]
+        public void Student_InheritsPerson_HasEnrollmentDate()
+        {
+            var student = new Student
+            {
+                LastName = "Test",
+                FirstMidName = "Student",
+                EnrollmentDate = new System.DateTime(2023, 9, 1)
+            };
+
+            Assert.Equal("Test, Student", student.FullName);
+            Assert.Equal(new System.DateTime(2023, 9, 1), student.EnrollmentDate);
+        }
+
+        [Fact]
+        public void Instructor_InheritsPerson_HasHireDate()
+        {
+            var instructor = new Instructor
+            {
+                LastName = "Test",
+                FirstMidName = "Instructor",
+                HireDate = new System.DateTime(2000, 1, 15)
+            };
+
+            Assert.Equal("Test, Instructor", instructor.FullName);
+            Assert.Equal(new System.DateTime(2000, 1, 15), instructor.HireDate);
+        }
+    }
+}
