+        [Fact]
+        public void SchoolContext_CanAddAndRetrieveStudent()
+        {
+            var dbName = Guid.NewGuid().ToString();
+            using (var context = TestDbContextHelper.CreateContext(dbName))
+            {
+                context.Students.Add(new Student
+                {
+                    FirstMidName = "Test",
+                    LastName = "User",
+                    EnrollmentDate = DateTime.Parse("2023-01-01")
+                });
+                context.SaveChanges();
+            }
+
+            using (var context = TestDbContextHelper.CreateContext(dbName))
+            {
+                var student = context.Students.Single();
+                Assert.Equal("Test", student.FirstMidName);
+                Assert.Equal("User", student.LastName);
+                Assert.Equal(DateTime.Parse("2023-01-01"), student.EnrollmentDate);
+            }
+        }
+
+        [Fact]
+        public void SchoolContext_CourseAssignment_HasCompositeKey()
+        {
+            using var context = TestDbContextHelper.CreateContext();
+
+            var instructor = new Instructor
+            {
+                FirstMidName = "Test",
+                LastName = "Instructor",
+                HireDate = DateTime.Parse("2020-01-01"),
+                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
+            };
+            context.Instructors.Add(instructor);
+
+            var dept = new Department
+            {
+                Name = "Test",
+                Budget = 100000,
+                StartDate = DateTime.Parse("2020-01-01")
+            };
+            context.Departments.Add(dept);
+            context.SaveChanges();
+
+            var course = new Course
+            {
+                CourseID = 9999,
+                Title = "Test Course",
+                Credits = 3,
+                DepartmentID = dept.DepartmentID
+            };
+            context.Courses.Add(course);
+            context.SaveChanges();
+
+            var assignment = new CourseAssignment
+            {
+                CourseID = course.CourseID,
+                InstructorID = instructor.ID
+            };
+            context.CourseAssignments.Add(assignment);
+            context.SaveChanges();
+
+            var found = context.CourseAssignments
+                .Single(ca => ca.CourseID == course.CourseID && ca.InstructorID == instructor.ID);
+            Assert.NotNull(found);
+        }
+
+        [Fact]
+        public void SchoolContext_TPH_StudentsAndInstructors_SharePeopleTable()
+        {
+            using var context = TestDbContextHelper.CreateContext();
+
+            context.Students.Add(new Student
+            {
+                FirstMidName = "Stu",
+                LastName = "Dent",
+                EnrollmentDate = DateTime.Today
+            });
+            context.Instructors.Add(new Instructor
+            {
+                FirstMidName = "Inst",
+                LastName = "Ructor",
+                HireDate = DateTime.Today,
+                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
+            });
+            context.SaveChanges();
+
+            // Both should appear in People table
+            Assert.Equal(2, context.People.Count());
+            Assert.Single(context.Students);
+            Assert.Single(context.Instructors);
+        }
+
+        [Fact]
+        public void SchoolContext_Instructor_HasOneToOneOfficeAssignment()
+        {
+            using var context = TestDbContextHelper.CreateContext();
+
+            var instructor = new Instructor
+            {
+                FirstMidName = "Test",
+                LastName = "Prof",
+                HireDate = DateTime.Today,
+                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>(),
+                OfficeAssignment = new OfficeAssignment { Location = "Room 101" }
+            };
+            context.Instructors.Add(instructor);
+            context.SaveChanges();
+
+            var loaded = context.Instructors
+                .Include(i => i.OfficeAssignment)
+                .Single(i => i.ID == instructor.ID);
+
+            Assert.NotNull(loaded.OfficeAssignment);
+            Assert.Equal("Room 101", loaded.OfficeAssignment.Location);
+            Assert.Equal(instructor.ID, loaded.OfficeAssignment.InstructorID);
+        }
+    }
+}
