+using System;
+using System.Collections.Generic;
+using ContosoUniversity.Controllers;
+using ContosoUniversity.Data;
+using ContosoUniversity.Models;
+using ContosoUniversity.Services;
+using Microsoft.AspNetCore.Mvc;
+using Xunit;
+
+namespace ContosoUniversity.Tests
+{
+    public class NotificationsControllerTests : IDisposable
+    {
+        private readonly SchoolContext _context;
+        private readonly NotificationsController _controller;
+
+        public NotificationsControllerTests()
+        {
+            TestDbContextHelper.DrainNotificationQueue();
+            _context = TestDbContextHelper.CreateContext();
+            _controller = new NotificationsController(_context);
+        }
+
+        public void Dispose()
+        {
+            _controller.Dispose();
+            _context.Dispose();
+            TestDbContextHelper.DrainNotificationQueue();
+        }
+
+        [Fact]
+        public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
+        {
+            var result = _controller.GetNotifications();
+
+            Assert.NotNull(result);
+            var data = result.Value as dynamic;
+            Assert.NotNull(data);
+        }
+
+        [Fact]
+        public void GetNotifications_WithNotifications_ReturnsNotifications()
+        {
+            // Enqueue some notifications via the notification service
+            var service = new NotificationService();
+            service.SendNotification("Student", "1", "Test Student", EntityOperation.CREATE, "admin");
+            service.SendNotification("Course", "2", "Test Course", EntityOperation.UPDATE, "admin");
+
+            var result = _controller.GetNotifications();
+
+            Assert.NotNull(result);
+            // The result is a JsonResult wrapping an anonymous object
+            Assert.IsType<JsonResult>(result);
+        }
+
+        [Fact]
+        public void GetNotifications_MoreThan10_LimitsTo10()
+        {
+            var service = new NotificationService();
+            for (int i = 0; i < 15; i++)
+            {
+                service.SendNotification("Test", i.ToString(), EntityOperation.CREATE, "admin");
+            }
+
+            var result = _controller.GetNotifications();
+
+            // Verify the controller returns a result (the limit of 10 is enforced internally)
+            Assert.IsType<JsonResult>(result);
+        }
+
+        [Fact]
+        public void MarkAsRead_ValidId_ReturnsSuccess()
+        {
+            var result = _controller.MarkAsRead(1);
+
+            Assert.NotNull(result);
+            Assert.IsType<JsonResult>(result);
+        }
+
+        [Fact]
+        public void Index_ReturnsView()
+        {
+            var result = _controller.Index() as ViewResult;
+
+            Assert.NotNull(result);
+        }
+    }
+}
+

