+using System;
+using ContosoUniversity.Controllers;
+using ContosoUniversity.Data;
+using ContosoUniversity.Models;
+using ContosoUniversity.Services;
+using Xunit;
+
+namespace ContosoUniversity.Tests
+{
+    public class BaseControllerTests : IDisposable
+    {
+        private readonly SchoolContext _context;
+
+        public BaseControllerTests()
+        {
+            TestDbContextHelper.DrainNotificationQueue();
+            _context = TestDbContextHelper.CreateContext();
+        }
+
+        public void Dispose()
+        {
+            _context.Dispose();
+            TestDbContextHelper.DrainNotificationQueue();
+        }
+
+        // Test through a concrete subclass (HomeController is simplest)
+        [Fact]
+        public void SendEntityNotification_DoesNotThrow()
+        {
+            using var controller = new HomeController(_context);
+
+            var exception = Record.Exception(() =>
+            {
+                // Use the controller to trigger operations that call SendEntityNotification
+                // Create a student via StudentsController
+            });
+
+            Assert.Null(exception);
+        }
+
+        [Fact]
+        public void Dispose_DisposesContextAndService()
+        {
+            var controller = new HomeController(_context);
+
+            var exception = Record.Exception(() => controller.Dispose());
+
+            Assert.Null(exception);
+        }
+
+        [Fact]
+        public void Dispose_CalledTwice_DoesNotThrow()
+        {
+            var ctx = TestDbContextHelper.CreateContext();
+            var controller = new HomeController(ctx);
+
+            controller.Dispose();
+            var exception = Record.Exception(() => controller.Dispose());
+
+            Assert.Null(exception);
+        }
+
+        [Fact]
+        public void SendEntityNotification_ViaStudentCreate_EnqueuesNotification()
+        {
+            var ctx = TestDbContextHelper.CreateContext();
+            using var controller = new StudentsController(ctx);
+
+            var student = new Student
+            {
+                FirstMidName = "Notify",
+                LastName = "Test",
+                EnrollmentDate = DateTime.Parse("2023-01-01")
+            };
+            controller.Create(student);
+
+            // Verify a notification was enqueued
+            var service = new NotificationService();
+            var notification = service.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Equal("Student", notification.EntityType);
+            Assert.Contains("created", notification.Message);
+            Assert.Contains("Notify Test", notification.Message);
+        }
+
+        [Fact]
+        public void SendEntityNotification_WithDisplayName_IncludesNameInMessage()
+        {
+            var ctx = TestDbContextHelper.CreateSeededContext();
+            using var controller = new DepartmentsController(ctx);
+
+            var dept = new Department
+            {
+                Name = "TestDept",
+                Budget = 100000,
+                StartDate = DateTime.Today
+            };
+            controller.Create(dept);
+
+            var service = new NotificationService();
+            var notification = service.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Equal("Department", notification.EntityType);
+            Assert.Contains("TestDept", notification.Message);
+        }
+
+        [Fact]
+        public void SendEntityNotification_WithoutDisplayName_UsesIdFormat()
+        {
+            var ctx = TestDbContextHelper.CreateSeededContext();
+            using var controller = new InstructorsController(ctx);
+
+            var instructor = new Instructor
+            {
+                FirstMidName = "No",
+                LastName = "Display",
+                HireDate = DateTime.Today,
+                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
+            };
+            controller.Create(instructor, null);
+
+            var service = new NotificationService();
+            var notification = service.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Equal("Instructor", notification.EntityType);
+            // InstructorsController uses the overload without displayName
+            Assert.Contains("ID:", notification.Message);
+        }
+    }
+}
